import{_ as s,o as t,c as a,a2 as i}from"./chunks/framework.7R1OEGYz.js";const k=JSON.parse('{"title":"Connect an MCP client","description":"","frontmatter":{},"headers":[],"relativePath":"mcp.md","filePath":"mcp.md","lastUpdated":null}'),n={name:"mcp.md"};function o(h,e,l,p,r,c){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="connect-an-mcp-client" tabindex="-1">Connect an MCP client <a class="header-anchor" href="#connect-an-mcp-client" aria-label="Permalink to &quot;Connect an MCP client&quot;">​</a></h1><p>An external MCP client can create sessions, read their transcripts, and send messages to your agents. Choose remote HTTP with browser sign-in, or a local stdio process with a personal API token. Both expose the same tool names.</p><h2 id="remote-http" tabindex="-1">Remote HTTP <a class="header-anchor" href="#remote-http" aria-label="Permalink to &quot;Remote HTTP&quot;">​</a></h2><p>AgentHub serves MCP at <code>https://hub.example.com/mcp</code> using <strong>Streamable HTTP</strong> and <strong>OAuth 2.1</strong>. AgentHub federates browser sign-in to your instance&#39;s OIDC provider. The endpoint is <strong>off by default</strong>.</p><h3 id="enable-the-endpoint" tabindex="-1">Enable the endpoint <a class="header-anchor" href="#enable-the-endpoint" aria-label="Permalink to &quot;Enable the endpoint&quot;">​</a></h3><p>Add this to your Helm values file and apply it using your normal <a href="/docs/upgrading">upgrade procedure</a>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">mcp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  publicUrl</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://hub.example.com&quot;</span></span></code></pre></div><p><code>mcp.publicUrl</code> is optional when your ingress host already supplies the correct HTTPS origin. It is the public origin, without <code>/mcp</code>, and becomes the OAuth issuer and token audience. The client and browser must be able to reach it.</p><p>Allow <code>https://hub.example.com/connect/oidc-callback</code> as a redirect URI for your instance&#39;s OIDC client. This is separate from the web UI&#39;s <code>/auth/callback</code> URI.</p><h3 id="connect-and-authenticate" tabindex="-1">Connect and authenticate <a class="header-anchor" href="#connect-and-authenticate" aria-label="Permalink to &quot;Connect and authenticate&quot;">​</a></h3><p>In Claude Code:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --transport</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://hub.example.com/mcp</span></span></code></pre></div><p>Run <code>/mcp</code> and authenticate in the browser. Sign in to the hub and approve the client&#39;s access. Other clients need remote HTTP transport and OAuth support; enter the same endpoint in their MCP settings. Client registration is automatic, and the authorization flow uses PKCE. Tools act as the user who approved the client and follow the hub&#39;s access checks.</p><p>On an instance without OIDC authentication, consent issues a token for the shared <code>dev</code> user. Configure instance authentication before exposing it to other people.</p><h2 id="local-stdio" tabindex="-1">Local stdio <a class="header-anchor" href="#local-stdio" aria-label="Permalink to &quot;Local stdio&quot;">​</a></h2><p>The stdio server is shipped as source under <a href="https://github.com/open-agenthub/open-agenthub/tree/main/mcp/agenthub" target="_blank" rel="noreferrer"><code>mcp/agenthub</code></a> in the main repository; the package name is <code>mcp-agenthub</code>. It uses a personal API token from <strong>Settings → API tokens</strong>, rather than the remote endpoint&#39;s OAuth flow.</p><p>Clone the repository locally, then install its dependencies:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> open-agenthub/mcp/agenthub</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span></code></pre></div><p>Configure your MCP client to launch Node with the absolute path to <code>server.mjs</code> and set <code>AGENTHUB_URL</code> and <code>AGENTHUB_TOKEN</code> in the client&#39;s environment configuration:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;agenthub&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;node&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/absolute/path/open-agenthub/mcp/agenthub/server.mjs&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;env&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;AGENTHUB_URL&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://hub.example.com&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;AGENTHUB_TOKEN&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;personal-api-token&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Adapt this example to your client&#39;s configuration format. The token starts with <code>oah_</code>; keep the real value local. The stdio server calls the token-authenticated API and does not require <code>mcp.enabled</code> or an OIDC browser login.</p><h2 id="first-checks" tabindex="-1">First checks <a class="header-anchor" href="#first-checks" aria-label="Permalink to &quot;First checks&quot;">​</a></h2><p>Ask the connected client to list your sessions with <code>session_list</code>. Use <code>session_logs</code> or <code>session_transcript</code> to read agent output; pod logs primarily show runtime startup. <code>agents_list</code> discovers agents and <code>agent_send</code> sends messages. Creating or changing sessions is a separate action from listing them.</p><table tabindex="0"><thead><tr><th>Symptom</th><th>Check</th></tr></thead><tbody><tr><td>HTTP 503: MCP endpoint disabled</td><td>Enable <code>mcp.enabled</code> and apply the Helm values.</td></tr><tr><td>HTTP 401 on remote HTTP</td><td>Complete the client&#39;s OAuth sign-in.</td></tr><tr><td>Identity provider reports <code>invalid_redirect_uri</code></td><td>Register the exact public <code>/connect/oidc-callback</code> URI.</td></tr><tr><td>Wrong issuer or unreachable authorization URL</td><td>Check <code>mcp.publicUrl</code>, ingress and HTTPS reachability.</td></tr><tr><td>Stdio authentication fails</td><td>Check <code>AGENTHUB_URL</code> and the personal API token in the client environment.</td></tr></tbody></table><p>MCP controls sessions; <a href="/docs/local-sessions">local continuation</a> uses separate archive helpers. For the full tool reference and OAuth endpoints, see the <a href="https://github.com/open-agenthub/open-agenthub/blob/main/docs/mcp-server.md" target="_blank" rel="noreferrer">MCP server documentation</a>.</p>`,25)])])}const u=s(n,[["render",o]]);export{k as __pageData,u as default};
